```ts
export function useFocusTrap(ref: React.RefObject<HTMLElement | null>): void {
  React.useEffect(() => {
    const prev = document.activeElement as HTMLElement | null;
    const el = ref.current;
    if (!el) return;
    const first = firstFocusable(el);
    (first ?? el).focus?.();
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return;
      const items = focusables(el);
      if (items.length === 0) return;
      const idx = items.indexOf(document.activeElement as HTMLElement);
      let next: number;
      if (e.shiftKey) next = idx <= 0 ? items.length - 1 : idx - 1;
      else next = idx === -1 || idx === items.length - 1 ? 0 : idx + 1;
      e.preventDefault();
      items[next].focus();
    };
    window.addEventListener('keydown', onKey, true); // capture so it wins over defaults
    return () => {
      window.removeEventListener('keydown', onKey, true);
      prev?.focus?.();
    };
  }, [ref]);
}
```
Note: the surface's element must be focusable or contain focusable elements. Buttons are focusable.

Hmm — should the trap only be active for the topmost surface? If the menu is open and the panel is on top: the menu's trap + the panel's trap both listen for Tab. The menu's trap would wrap focus to the menu's items — conflict. Fix: the trap should be active only when this surface is the top of the stack. Pass an `active` prop: `useFocusTrap(ref, active)`. EscMenu: active = topSurface()?.kind === 'menu'. ShipPanel: active = topSurface()?.kind === 'panel' && topSurface().id === myId. Chart: leave the chart as-is (no trap; existing behavior; it's a TASK-7 surface, don't touch its a11y).

